func dottedCallIdentifiers(content string, pattern *regexp.Regexp) map[string]struct{} {
	out := map[string]struct{}{}
	for _, match := range pattern.FindAllStringSubmatch(content, -1) {
		if len(match) < 2 {
			continue
		}
		name := lastDottedCallSegment(match[1])
		if name == "" {
			continue
		}
		out[name] = struct{}{}
	}
