				case raw[j] == '(' && raw[j+1] == '*':
					depth++
					j += 2
				case raw[j] == '*' && raw[j+1] == ')':
					depth--
					j += 2
				default:
					j++
				}
			}
			if depth > 0 {
				j = len(raw)
			}
			maskBytes(raw, i, j)
			i = j - 1
		case raw[i] == '/' && i+1 < len(raw) && raw[i+1] == '/':
			j := i + 2
			for j < len(raw) && raw[j] != '\n' && raw[j] != '\r' {
				j++
			}
			maskBytes(raw, i, j)
			i = j - 1
