			j := i + 3
			for j+2 < len(raw) && !(raw[j] == '"' && raw[j+1] == '"' && raw[j+2] == '"') {
				j++
			}
			if j+2 < len(raw) {
				j += 3
			} else {
				j = len(raw)
			}
			maskBytes(raw, i, j)
			i = j - 1
		case raw[i] == '@' && i+1 < len(raw) && raw[i+1] == '"':
			j := i + 2
			for j < len(raw) {
				if raw[j] != '"' {
					j++
					continue
				}
				if j+1 < len(raw) && raw[j+1] == '"' {
					j += 2 // an escaped quote inside a verbatim string
					continue
				}
				j++
				break
			}
			maskBytes(raw, i, j)
			i = j - 1
