			// An ordinary string, masked here so a `(*` or `//` inside one
			// cannot open a comment that swallows the rest of the file.
			j := i + 1
			for j < len(raw) && raw[j] != '\n' && raw[j] != '\r' {
				if raw[j] == '\\' {
					j += 2
					continue
				}
				if raw[j] == '"' {
					j++
					break
				}
				j++
			}
			maskBytes(raw, i, j)
			i = j - 1
		}
	}
