				switch {
				case raw[j] == '(' && raw[j+1] == '*':
					depth++
					j += 2
				case raw[j] == '*' && raw[j+1] == ')':
					depth--
					j += 2
				default:
					j++
				}
			}
			if depth > 0 {
				j = len(raw)
			}
			maskBytes(raw, i, j)
			i = j - 1
