// fsharpPipelineCallIdentifiers returns the functions applied by F# forward
// pipes (`value |> normalize`, `(a, b) ||> combine`, `xs |> List.map f`).
//
// The forward pipe is the dominant F# call idiom, and only module-qualified and
// parenthesised calls had a scanner: `fsharpDottedCallRe`/`fsharpDottedApplyRe`
// both require a dot, and the generic scanner requires `name(`. A bare piped
// function matched neither, so idiomatic pipelines produced no CALLS edge while
// `capabilities --json` advertises CALLS for F#.
//
// Only the pipe position is read. Bare juxtaposition elsewhere (`add 1 2`)
// needs the kind of application parser Haskell and OCaml have and is not
// guessed at here — an over-eager head-position heuristic would trade the
// precision the call graph is built on for recall.
func fsharpPipelineCallIdentifiers(content string) map[string]struct{} {
	return fsharpCallTargetNames(fsharpPipelineCallTargets(content))
}

// fsharpPipelineCallTargets returns the piped call targets as written, keeping
// the module qualifier of `xs |> A.convert` for resolution to hold the call to.
func fsharpPipelineCallTargets(content string) map[string]struct{} {
	return fsharpTargetsOfSites(fsharpPipelineCallSites(content))
}

// fsharpPipelineCallSites is fsharpPipelineCallTargets with the byte offset of
// every sighting kept beside the target it saw.
func fsharpPipelineCallSites(content string) map[string][]int {
	stripped := maskFSharpLiteralsAndLineComments(content)
	out := map[string][]int{}
	for _, match := range fsharpPipelineCallRe.FindAllStringSubmatchIndex(stripped, -1) {
		if len(match) < 4 || match[2] < 0 {
			continue
		}
		if !fsharpIsForwardPipeOperator(stripped, match[0]) {
			continue
		}
		target := stripped[match[2]:match[3]]
		if fsharpPipelineTargetIgnored(target) {
			continue
		}
		addFSharpCallSite(out, target, match[2])
	}
	return out
}

// fsharpIsForwardPipeOperator reports whether the `|>` starting at pipeStart is
// a whole forward-pipe operator rather than a fragment of a longer one.
//
// F# lexes a run of operator characters as a single token and lets users define
// their own, so plenty of legal operators merely *contain* `|>`: FParsec's and
// FSharpPlus's alternative combinator `<|>` (`digit <|> letter`), and any custom
// `+|>`, `^|>`, `.|>`. In those the right operand is an alternative or the
// custom operator's own argument, not a function being handed the left one, so
		// `let` does: `let run (Json: JsonConvert) x = Json.serialize x` names
		// the parameter, not the project module `Json`. Their scope is the body
		// the header opens rather than the block the header sits in, so it is
		// closed by the next line at the header's OWN indent -- the sibling
		// binding after the function -- not only by a dedent past it.
		//
		// A parameter is bound by the HEADER, not by an initializer, so unlike
		// a `let` it shadows from the header line itself: the body of
		// `let run (Json: JsonConvert) x = Json.serialize x` is written there.
		//
		// The header is read as a LOGICAL line, because F# lets one span
		// several physical ones. Parameter extraction ended at the `=` and
		// gave up on a line that had none, so `let run` followed by an
		// indented `(Json: JsonConvert) =` bound nothing at all and the
		// qualifier was classified by the project's module declarations alone
		// -- the fabricated-edge direction again, into an unrelated project
		// module `Json`.
		for _, name := range fsharpFunctionParameterNames(fsharpJoinedFunctionHeader(lines, index)) {
			bindings = append(bindings, fsharpShadowBinding{
				name:        name,
				fromLine:    index + 1,
				throughLine: fsharpParameterScopeEnd(lines, index),
			})
		}
	}
	return bindings
}

// fsharpShadowBindingAt returns the name this line binds lexically; when the
// binder is a module abbreviation, the module path it binds that name TO; and
// whether the binding is RECURSIVE, which decides whether it shadows inside its
// own initializer. A name bound to no module path -- a value, a parameter --
// comes back with an empty target. The name is empty if the line binds nothing.
//
// A module abbreviation is never recursive: `module Json = Newtonsoft.Json`
// resolves its right-hand side in the scope OUTSIDE itself, exactly as a
// non-recursive `let` does.
func fsharpShadowBindingAt(line string) (string, string, bool) {
	if match := fsharpModuleAbbreviationPattern.FindStringSubmatch(line); match != nil {
		// `module M = begin ... end` is the verbose spelling of a nested module
		// BLOCK, not an abbreviation: it binds no alias, it opens a scope. It is
		// the one right-hand side that has to be excluded, which is why the
		// pattern captures the word rather than guessing from its case.
		if match[2] == "begin" {
			return "", "", false
		}
		return match[1], match[2], false
	}
	if match := fsharpValueBindingPattern.FindStringSubmatch(line); match != nil {
		return match[2], "", slices.Contains(strings.Fields(match[1]), "rec")
	}
	return "", "", false
}

// fsharpBindingScopeStart returns the first POINT -- line and 0-based byte
// column on it -- from which the binding written on lines[index] shadows its
// name.
//
// Three of the four answers are whole lines and were already settled: `rec`
// asks for the binding's own line, because the name is in scope inside its own
// body; without it the shadow starts on the line after the initializer ends,
		// `List.map` from inside a block comment); the pipeline scanner matches
		// its sibling rather than diverging from it here.
		{"block comment matches the dotted scanner", "let f () = 1 (* xs |> helper *)", []string{"helper"}},
		{"qualified pipe", "let f xs = xs |> List.map g", []string{"map"}},
		{"bare pipe", "let f xs = xs |> helper", []string{"helper"}},
		{"double pipe", "let f a b = (a, b) ||> helper", []string{"helper"}},
		{"triple pipe", "let f a b c = (a, b, c) |||> helper", []string{"helper"}},
		// `<|>` is FParsec's and FSharpPlus's alternative combinator. It
		// contains a literal `|>` but applies nothing — the right operand is an
		// alternative, not a function being handed the left one — so reading it
		// as a forward pipe invents a call.
		{"alternative combinator is not a pipe", "let p = digit <|> helper", nil},
		{"alternative combinator without spaces", "let p = digit<|>helper", nil},
		{"backward pipe", "let f x = helper <| x", nil},
		{"pipes chained without spaces", "let f xs = xs|>helper|>g", []string{"helper", "g"}},
		// F# lexes a run of operator characters as one token and lets users
		// define their own, so many legal operators merely contain `|>`. Their
		// right operand is the custom operator's argument, not a function being
		// applied, so matching the bare substring fabricates a call.
		{"custom operator containing a pipe", "let f x = x +|> helper", nil},
		{"custom operator with a caret", "let f x = x ^|> helper", nil},
		{"custom operator with a dot", "let f x = x .|> helper", nil},
		{"custom operator with a bang", "let f x = x !|> helper", nil},
		{"custom operator without spaces", "let f x = x+|>helper", nil},
		{"FParsec map operator", "let p = a |>> helper", nil},
		// The genuine tuple pipes stay pipes: they feed the token on their
		// right more arguments, but it is still the function being applied.
		{"double pipe without spaces", "let f a b = (a, b)||>helper", []string{"helper"}},
		{"triple pipe without spaces", "let f a b c = (a, b, c)|||>helper", []string{"helper"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := fsharpPipelineCallIdentifiers(tc.content)
			if len(got) != len(tc.want) {
				t.Fatalf("got %v, want %v", got, tc.want)
			}
			for _, name := range tc.want {
				if _, ok := got[name]; !ok {
					t.Fatalf("missing %q in %v", name, got)
				}
			}
		})
	}
}

