`)
		writeFile(t, repo, "src/Serde.fs", `module Serde

let serialize (x: int) = x + 3
`)
		writeFile(t, repo, "src/Deep.fs", `namespace Deep

module Serde =
    let serialize (x: int) = x + 5
`)
		writeFile(t, repo, "src/Use.fs", useSource)
